def src(id,title,url,local=None,notes=''):
 s={'id':id,'title':title,'url':url,'verifiedOn':'2026-11-25','notes':notes}
 if local:s['localFile']=str(P/local)
 sources.append(s);return id
def pub(pid,fid):return f'https://publications.saskatchewan.ca/api/v1/products/{pid}/formats/{fid}/download'
def field(label,type='text',requiredness='unknown',**kw):
 return {'id':re.sub(r'[^a-z0-9]+','_',label.lower()).strip('_'),'label':label,'type':type,'requiredness':requiredness,**kw}
def sec(title,fields,owner='Applicant',**kw):return {'title':title,'owner':owner,'fields':[field(x) if isinstance(x,str) else x for x in fields],**kw}
def add(id,title,sourceId,sections,requiredness='required',stage='application',condition='',kind='form',**kw):
 f={'id':id,'title':title,'facilityType':'centre','scope':'opening','requiredness':requiredness,'condition':condition,'stage':stage,'kind':kind,'availability':'downloaded_verified','digitization':'structured_fields','sourceIds':[sourceId],'sections':sections,'attachments':[],'reviewerFields':[],'notes':[],**kw};forms.append(f);return f
